function [config_s, groups] = rfdude_pll_configuration()
% Generated by GitHub Copilot under Lance Lascari's direction.
% Use the human-created run script as the authority for defaults and ordering.
source=fileread(fullfile(fileparts(mfilename('fullpath')),'aa_RunPllDesign_XXXX.m'));
lines=regexp(source,'\r\n|\n','split');
inputs=struct();
for k=1:numel(lines)
    token=regexp(lines{k},'^pll_inputs_s\.(\w+)\s*=\s*([^;%]+)','tokens','once');
    if isempty(token)
        continue;
    end
    text=strtrim(token{2});
    if text(1)=='''' || text(1)=='"'
        value=text(2:end-1);
    else
        value=rfdude_pll_parse_value(text);
    end
    inputs.(token{1})=value;
end
config_s.pll_inputs_s=inputs;
config_s.run_options_s=struct('bRunSweep',false, ...
    'sweep_parameter','BW_desired_Hz','sweep_values',[1000 2000 4000], ...
    'integration_lower_Hz',100,'integration_upper_Hz',1e6, ...
    'noise_offsets_Hz',[100 1000 10000 100000], ...
    'bShowCorePlots',true,'bEnableDataViewer',true,'bOverwriteResults',false);
groups={ ...
    'System', {'fout_desired_Hz','mult','Fref_Hz','Kvco_Hz_volt', ...
        'Kphi_A_cycle','BW_desired_Hz','PM_desired_deg','ATTEN_dB'}; ...
    'Reference noise', {'bUseTCXOFromFile','F_tcxo_Hz','FileTCXO', ...
        'Ntcxo_ref_dBc','Ftcxo_ref_offset_Hz','Npd_ref_dBc'}; ...
    'VCO noise', {'bUseVCOFromFile','FileVCO','Nvco_ref_dBc','Fvco_ref_offset_Hz'}; ...
    'Loop filter', {'filter_override','filter_override_3rdpole_only', ...
        'CC1','CC2','RR2','CC3','RR3'}; ...
    'Frequency / output', {'def_filename','fstart_main_Hz','fstop_main_Hz', ...
        'fsweep_main_pts','pn_ylimits','bSaveFigs','bSaveFigsPDF', ...
        'bSaveFigsJPG','bWriteCSVtable'}; ...
    'Transient', {'bDoTransient','transient_delta_f_Hz','transient_tmax_s', ...
        'transient_points','transient_ftol_Hz','bDoTransientNonlinear', ...
        'transient_nl_steps_per_ref','transient_nl_fvco_min_Hz', ...
        'transient_nl_fvco_max_Hz'}};
end
